from typing import List; exec("class Solution:\n    def get_merges(self, corpus, num_merges):\n        tokens = list(corpus)\n        merges = []\n        for _ in range(num_merges):\n            if len(tokens) < 2:\n                break\n            pairs = {}\n            for i in range(len(tokens) - 1):\n                pair = (tokens[i], tokens[i+1])\n                pairs[pair] = pairs.get(pair, 0) + 1\n            if not pairs:\n                break\n            best_count = max(pairs.values())\n            candidates = sorted(p for p, c in pairs.items() if c == best_count)\n            best = candidates[0]\n            merges.append([best[0], best[1]])\n            new_tokens = []\n            i = 0\n            while i < len(tokens):\n                if i < len(tokens) - 1 and tokens[i] == best[0] and tokens[i+1] == best[1]:\n                    new_tokens.append(best[0] + best[1])\n                    i += 2\n                else:\n                    new_tokens.append(tokens[i])\n                    i += 1\n            tokens = new_tokens\n        return merges")